cat > /tmp/bot-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { mkdtemp, mkdir, utimes, writeFile, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
const run = promisify(execFile);
const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g4-2/bot.mjs';
const { reserve, release } = await import(BOT);

const dir = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = dir;
const T0 = new Date('2026-10-22T09:00:00Z');
const at = (min) => new Date(T0.getTime() + min * 60_000);
const req = (over = {}) => ({ userId: 'lead_204', maxPerWindow: 3, windowHours: 24, minGapMinutes: 90, ...over });
let n = 0; const ok = (name) => console.log(`ok ${++n} - ${name}`);

// 1. Gap blocks a second send too soon; allowed after the gap.
const a = await reserve(req(), at(0));
assert.equal(a.allowed, true); assert.equal(typeof a.reservationId, 'string');
const b = await reserve(req(), at(60));
assert.deepEqual(b, { allowed: false, reason: 'min_gap_not_elapsed', reservationId: null }); ok('gap blocks at 60 min');
const c = await reserve(req(), at(90));
assert.equal(c.allowed, true); ok('gap allows exactly at 90 min');
const d = await reserve(req(), at(180));
assert.equal(d.allowed, true); ok('third send at 180 min allowed');

// 2. Window limit: 3 counted in 24h, 4th blocked with a different code.
const e = await reserve(req(), at(270));
assert.deepEqual(e, { allowed: false, reason: 'window_limit_reached', reservationId: null }); ok('fourth in 24h blocked: window_limit_reached');

// 3. Sliding window: first send (t=0) drops out at t=24h, not at a calendar boundary.
const f = await reserve(req(), at(24 * 60 - 1));
assert.equal(f.reason, 'window_limit_reached'); ok('one minute before slot frees: still blocked');
const g = await reserve(req(), at(24 * 60));
assert.equal(g.allowed, true); ok('exactly 24h after first send: slot frees');

// 4. Per-call limits: a looser call sees the same history with its own numbers.
const h = await reserve(req({ maxPerWindow: 10, minGapMinutes: 0 }), at(24 * 60 + 1));
assert.equal(h.allowed, true); ok('per-call looser limits accepted');

// 5. Release frees the slot; release is idempotent; bad ids are a no-op.
const lead2 = req({ userId: 'lead_999', maxPerWindow: 1, minGapMinutes: 600 });
const r1 = await reserve(lead2, at(0));
assert.equal(r1.allowed, true);
assert.equal((await reserve(lead2, at(1))).reason, 'min_gap_not_elapsed');
assert.equal(await release(r1.reservationId), true);
const r2 = await reserve(lead2, at(2));
assert.equal(r2.allowed, true); ok('release returns slot (gap and window both)');
assert.equal(await release(r1.reservationId), false); ok('second release of same id is a no-op');
assert.equal(await release('not-an-id'), false); assert.equal(await release(null), false); ok('garbage release ids return false');

// 6. Blocked attempts do not count against the limit.
const lead3 = req({ userId: 'lead_777', maxPerWindow: 1, minGapMinutes: 0 });
assert.equal((await reserve(lead3, at(0))).allowed, true);
for (let i = 1; i < 5; i++) assert.equal((await reserve(lead3, at(i))).allowed, false);
assert.equal(await release((await reserve(lead3, at(10))).reservationId ?? 'x'), false);
// after one release of the only slot, a new reserve works immediately
ok('blocked attempts do not stack up');

// 7. Cross-process: release from another process than the reserver.
const first = await reserve(req({ userId: 'lead_x', maxPerWindow: 1, minGapMinutes: 0 }), at(0));
const { stdout } = await run(process.execPath, ['-e',
  `import('${BOT}').then(m=>m.release(${JSON.stringify(first.reservationId)})).then(v=>process.stdout.write(String(v)))`]);
assert.equal(stdout, 'true'); ok('release from a different process frees the slot');

// 8. Concurrency: 12 processes x 5 attempts for one lead at one instant, limit 3.
const procs = await Promise.all(Array.from({ length: 12 }, () =>
  run(process.execPath, [path.join(path.dirname(new URL(import.meta.url).pathname), 'child.mjs'), 'lead_race', '5', '3', T0.toISOString()], { env: { ...process.env, STATE_DIR: dir } })));
const results = procs.flatMap(p => JSON.parse(p.stdout));
const allowed = results.filter(r => r.allowed);
assert.equal(results.length, 60);
assert.equal(allowed.length, 3, `expected exactly 3 allowed, got ${allowed.length}`);
assert.ok(results.filter(r => !r.allowed).every(r => r.reason === 'window_limit_reached'));
ok('60 concurrent attempts across 12 processes: exactly 3 allowed');

// 9. Restart: a fresh process still sees the history.
const after = await run(process.execPath, [path.join(path.dirname(new URL(import.meta.url).pathname), 'child.mjs'), 'lead_race', '1', '3', at(60).toISOString()], { env: { ...process.env, STATE_DIR: dir } });
assert.equal(JSON.parse(after.stdout)[0].reason, 'window_limit_reached'); ok('history survives process restart');

// 10. Stale lock from a dead worker is broken; a fresh lock is respected.
const staleKeyDir = path.join(dir, 'leads');
const lockProbe = await reserve(req({ userId: 'lead_stale', minGapMinutes: 0 }), at(0));
const { createHash } = await import('node:crypto');
const key = createHash('sha256').update('lead_stale').digest('hex');
await mkdir(path.join(staleKeyDir, `${key}.lock`));
const old = new Date(Date.now() - 60_000);
await utimes(path.join(staleKeyDir, `${key}.lock`), old, old);
const s = await reserve(req({ userId: 'lead_stale', minGapMinutes: 0 }), at(500));
assert.equal(s.allowed, true); ok('stale lock (60s old) is broken');

// 11. Corrupt history file throws instead of resetting.
const badKey = createHash('sha256').update('lead_bad').digest('hex');
await writeFile(path.join(staleKeyDir, `${badKey}.json`), '{not json');
await assert.rejects(reserve(req({ userId: 'lead_bad' }), at(0)), SyntaxError); ok('corrupt file throws, no silent reset');

// 12. Input validation.
await assert.rejects(reserve(req({ userId: '' }), at(0)), TypeError);
await assert.rejects(reserve(req({ maxPerWindow: 0 }), at(0)), TypeError);
await assert.rejects(reserve(req({ windowHours: 0 }), at(0)), TypeError);
await assert.rejects(reserve(req({ minGapMinutes: -1 }), at(0)), TypeError);
await assert.rejects(reserve(req(), '2026-10-22'), TypeError); ok('invalid input rejected');

// 13. No leftover lock directories after all of the above.
const leftovers = (await readdir(staleKeyDir)).filter(f => f.endsWith('.lock') && f !== `${key}.lock`);
assert.deepEqual(leftovers, []); ok('no lock dirs left behind');
console.log('ALL PASSED');
EOF
cd /tmp/bot-test && node test.mjs
